def countAnagrams(s: str) -> int:
    s = s
    ways = 1
    MOD = 10**9 + 7
    words = s.split(' ')

    for word in words:
        fact = 1
        for i in range(1, len(word) + 1):
            fact *= i

        hashmap = {}
        for char in word:
            hashmap[char] = hashmap.get(char, 0) + 1

        for value in hashmap.values():
            fact //= factorial(value)

        ways = (ways * fact) % MOD

    return ways

def factorial(n):
    if n <= 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result
